/** @noSelfInFile **/

export const ImGui: ImGuiShim;

type ImGuiShim = {
  [K in ImGuiFunctions]: `ImGui_${K}` extends keyof typeof reaper
    ? (typeof reaper)[`ImGui_${K}`]
    : never;
} & {
  [K in ImGuiConstants]: number;
};

